```js
export function brickHit(ball, bricks) {
  let bounced = false;
  let hitBrick = null;
  let best = Infinity;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    // compute side penetration
    const rightPen = ball.x + ball.r - brick.x;
    const leftPen = brick.x + brick.w - (ball.x - ball.r);
    const topPen = ball.y + ball.r - brick.y;
    const bottomPen = brick.y + brick.h - (ball.y - ball.r);
    const minPen = Math.min(rightPen, leftPen, topPen, bottomPen);
    if (minPen < best) {
      best = minPen;
      hitBrick = brick;
    }
  }
  if (hitBrick) {
    bounceOff(ball, hitBrick);
    hitBrick.alive = false;
    bounced = true;
  }
  return hitBrick; // or alive set
}
```

