// --- Issue #1: brick bounce -----------------------------------------------

test('bounce off the top face: flips vy down, keeps vx untouched', () => {
  const ball = { x: 100, y: 55, r: 7, vx: 30, vy: -200 };
  const brick = { x: 90, y: 60, w: 40, h: 20 };
  bounceOff(ball, brick);
  assert.equal(ball.vy, 200, 'vy should flip to DOWNWARD');
  assert.equal(ball.vx, 30, 'vx must be left exactly as it was');
  assert.equal(collides(ball, brick), false, 'ball pushed out of the brick');
});

test('bounce off the bottom face: flips vy up, keeps vx untouched', () => {
  const ball = { x: 100, y: 100, r: 7, vx: -20, vy: 200 };
  const brick = { x: 90, y: 60, w: 40, h: 20 };
  bounceOff(ball, brick);
  assert.equal(ball.vy, -200, 'vy should flip to UPWARD');
  assert.equal(ball.vx, -20, 'vx must be left exactly as it was');
  assert.equal(collides(ball, brick), false);
});

test('bounce off the left face: flips vx, keeps vy untouched', () => {
  const ball = { x: 80, y: 70, r: 7, vx: 300, vy: -20 };
  const brick = { x: 90, y: 60, w: 40, h: 20 };
  bounceOff(ball, brick);
  assert.equal(ball.vx, -300, 'vx should flip LEFT');
  assert.equal(ball.vy, -20, 'vy must be left exactly as it was');
  assert.equal(collides(ball, brick), false);
});

test('bounce off the right face: flips vx, keeps vy untouched', () => {
  const ball = { x: 145, y: 70, r: 7, vx: -300, vy: -20 };
  const brick = { x: 90, y: 60, w: 40, h: 20 };
  bounceOff(ball, brick);
  assert.equal(ball.vx, 300, 'vx should flip RIGHT');
  assert.equal(ball.vy, -20, 'vy must be left exactly as it was');
  assert.equal(collides(ball, brick), false);
});

test('corner hit (equal penetration): flips both components', () => {
  const ball = { x: 96, y: 66, r: 7, vx: 300, vy: 200 };
  const brick = { x: 90, y: 60, w: 40, h: 20 };
  bounceOff(ball, brick);
  assert.Equal = undefined; // noop guard (unused)
  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, -200);
  assert.equal(collides(ball, brick), false);
});

test('step: smashes a brick and bounces the ball upward', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 40, r: 7, vx: 0, vy: 200 };
  state.bricks = [{ x: 90, y: 60, w: 40, h: 20, alive: true, points: 10 }];
  const lost = step(state, 1 / 5);
  assert.equal(lost, false);
  assert.equal(state.bricks[0].alive, false, 'brick should be destroyed');
  assert.ok(state.ball.vy < 0, 'ball should bounce upward after a top hit');
  assert.ok(state.score > 0, 'score should be awarded');
});

test('step: seam of two adjacent bricks bounces exactly once', () => {
  const state = createState(1);
  state.ball = { x: 130, y: 40, r: 7, vx: 0, vy: 300 };
  state.bricks = [
    { x: 90, y: 60, w: 40, h: 20, alive: true, points: 10 },
    { x: 130, y: 60, w: 40, h: 20, alive: true, points: 10 },
  ];
  step(state, 1 / 5);
  assert.ok(state.ball.vy < 0, 'ball must have bounced upward (not double-flipped back through)');
  assert.equal(
    state.bricks.filter((b) => !b.alive).length,
    1,
    'only one brick destroyed per pass at the seam'
  );
});

test('step: high speed does NOT tunnel through a brick (substepping)', () => {
  const state = createState(6);
  state.ball = { x: 100, y: 30, r: 7, vx: 0, vy: 1500 };
  state.bricks = [{ x: 90, y: 60, w: 40, h: 20, alive: true, points: 100 }];
  const lost = step(state, 0.05);
  assert.equal(lost, false);
  assert.equal(state.bricks[0].alive, false, 'ball must not skip over the brick');
  assert.ok(state.ball.vy < 0, 'ball should bounce upward instead of tunneling');
});

